const PAINT_BY_ID = new Map(LIBRARY_PAINTS.map((p) => [p.id, p]));

export function paintById(id: string): BoardPaint | undefined {
    return PAINT_BY_ID.get(id);
}

export function isLibraryPaint(value: unknown): value is string {
    return typeof value === 'string' && PAINT_BY_ID.has(value);
}

